// src/cli.ts
var cachedCLIPath = null;
var cachedInstancePath = null;
async function findCLI() {
  if (cachedCLIPath !== null)
    return cachedCLIPath;
  try {
    const proc = Bun.spawn(["which", "epf-cli"], {
      stdout: "pipe",
      stderr: "pipe"
    });
    const stdout = await new Response(proc.stdout).text();
    const exitCode = await proc.exited;
    if (exitCode === 0 && stdout.trim()) {
      cachedCLIPath = stdout.trim();
      return cachedCLIPath;
    }
  } catch {}
  cachedCLIPath = null;
  return null;
}
async function execCLI(args, timeoutMs = 30000) {
  const cliPath = await findCLI();
  if (!cliPath) {
    return {
      stdout: "",
      stderr: "epf-cli not found on PATH",
      exitCode: 127
    };
  }
  const controller = new AbortController;
  const timeout = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const proc = Bun.spawn([cliPath, ...args], {
      stdout: "pipe",
      stderr: "pipe",
      signal: controller.signal
    });
    const [stdout, stderr] = await Promise.all([
      new Response(proc.stdout).text(),
      new Response(proc.stderr).text()
    ]);
    const exitCode = await proc.exited;
    return { stdout, stderr, exitCode };
  } catch (err) {
    const message = err instanceof Error ? err.message : "Unknown error executing epf-cli";
    return {
      stdout: "",
      stderr: message,
      exitCode: 1
    };
  } finally {
    clearTimeout(timeout);
  }
}
async function execCLIJson(args, timeoutMs = 30000) {
  const result = await execCLI(args, timeoutMs);
  if (result.exitCode === 127) {
    return {
      ok: false,
      data: null,
      error: "epf-cli not found on PATH",
      exitCode: 127
    };
  }
  if (result.exitCode !== 0 && !result.stdout.trim()) {
    return {
      ok: false,
      data: null,
      error: result.stderr.trim() || `epf-cli exited with code ${result.exitCode}`,
      exitCode: result.exitCode
    };
  }
  const text = result.stdout.trim();
  if (!text) {
    return {
      ok: false,
      data: null,
      error: "No output from epf-cli",
      exitCode: result.exitCode
    };
  }
  try {
    const data = JSON.parse(text);
    return {
      ok: result.exitCode === 0,
      data,
      error: result.exitCode !== 0 ? result.stderr.trim() || null : null,
      exitCode: result.exitCode
    };
  } catch {
    return {
      ok: false,
      data: null,
      error: `Failed to parse JSON output from epf-cli: ${text.slice(0, 200)}`,
      exitCode: result.exitCode
    };
  }
}
async function detectInstance(directory) {
  if (cachedInstancePath !== null)
    return cachedInstancePath || null;
  const result = await execCLI([
    "locate",
    directory,
    "--require-anchor",
    "--json"
  ]);
  if (result.exitCode !== 0 || !result.stdout.trim()) {
    cachedInstancePath = "";
    return null;
  }
  try {
    const data = JSON.parse(result.stdout.trim());
    const valid = data.instances?.filter((i) => i.status === "valid") ?? [];
    if (valid.length > 0) {
      const confidenceOrder = {
        high: 3,
        medium: 2,
        low: 1
      };
      valid.sort((a, b) => (confidenceOrder[b.confidence] ?? 0) - (confidenceOrder[a.confidence] ?? 0));
      cachedInstancePath = valid[0].path;
      return cachedInstancePath;
    }
  } catch {}
  cachedInstancePath = "";
  return null;
}
async function runHealthCheck(instancePath) {
  return execCLIJson(["health", instancePath, "--json"]);
}
async function runCoverage(instancePath, track) {
  const args = ["coverage", instancePath, "--json"];
