var PLUGIN_VERSION = "0.3.0";
var MAX_LEDGER_ENTRIES = 500;

class ToolCallLedger {
  entries = [];
  record(toolName, success) {
    if (!toolName.startsWith("epf_"))
      return;
    this.entries.push({
      toolName,
      timestamp: new Date().toISOString(),
      success
    });
    if (this.entries.length > MAX_LEDGER_ENTRIES) {
      this.entries.shift();
    }
  }
  getMissing(expectedTools) {
    const calledSet = new Set(this.entries.map((e) => e.toolName));
    return expectedTools.filter((t) => !calledSet.has(t));
